// wb-autotrader click — activate a control on a contract route.
//
// A "click" on a server-rendered clone is either a form submission (the control
// sits inside a <form>) or a navigation (the control is an <a href>). Both are
// resolved from the fetched markup, never guessed.
//
// Generated by `websitebench-harbor opencli-adapters`. Do not hand-edit.

import { cli, Strategy } from '@jackwener/opencli/registry';
import { CommandExecutionError } from '@jackwener/opencli/errors';

import {
  enclosingForm,
  findAll,
  mergeCookies,
  observationRows,
  parseExpect,
  request,
  resolveRoute,
  serializeForm,
} from './_wb.js';

cli({
  site: 'wb-autotrader',
  name: 'click',
  access: 'write',
  description: 'Activate a AutoTrader UK offline-clone control by selector (form submit or link follow)',
  domain: '127.0.0.1',
  strategy: Strategy.LOCAL,
  browser: false,
  args: [
    { name: 'route', type: 'string', default: '', help: 'Contract-relative route hosting the control' },
    { name: 'base', type: 'string', default: 'http://127.0.0.1:8080', help: 'Clone base URL' },
    { name: 'selector', type: 'string', default: '', help: 'Selector of the control to activate' },
    { name: 'expect', type: 'string', default: '', help: 'JSON object of contract required_state' },
    { name: 'session', type: 'string', default: '', help: 'Cookie header to send' },
    { name: 'timeout', type: 'int', default: 15, help: 'Request timeout in seconds' },
  ],
  columns: ['route', 'status', 'action', 'target', 'checkKey', 'expected', 'observed', 'passed', 'asserted', 'setCookie'],
  func: async (args) => {
    const url = resolveRoute(args.base, args.route);
    const expect = parseExpect(args.expect);
    const page = await request(url, { session: args.session, timeout: args.timeout });
    let session = mergeCookies(args.session, page.setCookie);

    const matches = findAll(page.body, args.selector);
    if (matches.length === 0) {
      throw new CommandExecutionError(
        `selector matched no element on ${args.route}`,
        `selector: ${args.selector}`,
      );
    }
    const target = matches[0];

    let result;
    let action;
    let targetDescription;
    const form = enclosingForm(page.body, target.start);
    if (form) {
      action = 'submit';
      targetDescription = form.attributes.action || args.route;
      const method = (form.attributes.method || 'GET').toUpperCase();
      const payload = serializeForm(form);
      const formUrl = resolveRoute(args.base, targetDescription);
      result =
        method === 'POST'
          ? await request(formUrl, { method: 'POST', body: payload, session, timeout: args.timeout, referer: url })
          : await request(`${formUrl}?${payload}`, { session, timeout: args.timeout, referer: url });
    } else if (target.tag === 'a' && target.attributes.href) {
      action = 'navigate';
      targetDescription = target.attributes.href;
      result = await request(resolveRoute(args.base, targetDescription), {
        session,
        timeout: args.timeout,
        referer: url,
      });
    } else {
      throw new CommandExecutionError(
        `selector matched <${target.tag}> which is neither a form control nor a link`,
        `selector: ${args.selector}`,
      );
    }
    session = mergeCookies(session, result.setCookie);

    // A 3xx is the success signal for a mutation; follow it so required_state
    // is evaluated against the page the user would actually land on.
    let observed = result;
    if (result.status >= 300 && result.status < 400 && result.location) {
      observed = await request(resolveRoute(args.base, result.location), {
        session,
        timeout: args.timeout,
      });
      session = mergeCookies(session, observed.setCookie);
    }

    return observationRows(
      {
        route: args.route,
        status: result.status,
        action,
        target: targetDescription,
        setCookie: session,
      },
      observed,
      expect,
    );
  },
});
